import{_ as i,a0 as p,w as l,s as u,I as s,x as e,a1 as n,A as r,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"使用 Linux 自动化工具提高生产率 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 自动化工具提高生产率 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 自动化工具提高生产率 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 自动化工具提高生产率 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210203 Improve your productivity with this Linux automation tool","title":"使用 Linux 自动化工具提高生产率","tag":"202104","desc":""},"relativePath":"202104/20210203 Improve your productivity with this Linux automation tool.md","filePath":"[post].md"}'),d={name:"202104/20210203 Improve your productivity with this Linux automation tool.md"};function y(b,t,g,k,f,m){const a=p("Link");return l(),u("div",null,[t[38]||(t[38]=s("h1",{id:"使用-linux-自动化工具提高生产率",tabindex:"-1"},[e("使用 Linux 自动化工具提高生产率 "),s("a",{class:"header-anchor",href:"#使用-linux-自动化工具提高生产率","aria-label":"Permalink to “使用 Linux 自动化工具提高生产率”"},"​")],-1)),t[39]||(t[39]=s("blockquote",null,[s("p",null,"用 AutoKey 配置你的键盘，纠正常见的错别字，输入常用的短语等等。")],-1)),t[40]||(t[40]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/30/111130s7ffji6cmb7rkcfx.jpg",alt:""})],-1)),s("p",null,[n(a,{href:"https://github.com/autokey/autokey"},{default:r(()=>[...t[0]||(t[0]=[e("AutoKey",-1)])]),_:1}),t[1]||(t[1]=e(" 是一个开源的 Linux 桌面自动化工具，一旦它成为你工作流程的一部分，你就会想，如何没有它，那该怎么办。它可以成为一种提高生产率的变革性工具，或者仅仅是减少与打字有关的身体压力的一种方式。",-1))]),t[41]||(t[41]=s("p",null,"本文将研究如何安装和开始使用 AutoKey ，介绍一些可以立即在工作流程中使用的简单方法，并探讨 AutoKey 高级用户可能会感兴趣的一些高级功能。",-1)),t[42]||(t[42]=s("h3",{id:"安装并设置-autokey",tabindex:"-1"},[e("安装并设置 AutoKey "),s("a",{class:"header-anchor",href:"#安装并设置-autokey","aria-label":"Permalink to “安装并设置 AutoKey”"},"​")],-1)),s("p",null,[t[3]||(t[3]=e("AutoKey 在许多 Linux 发行版中都是现成的软件包。该项目的 ",-1)),n(a,{href:"https://github.com/autokey/autokey/wiki/Installing"},{default:r(()=>[...t[2]||(t[2]=[e("安装指南",-1)])]),_:1}),t[4]||(t[4]=e(" 包含许多平台的说明，也包括了从源代码进行构建的指导。本文使用 Fedora 作为操作平台。",-1))]),s("p",null,[t[7]||(t[7]=e("AutoKey 有两个变体：为像 GNOME 等基于 ",-1)),n(a,{href:"https://www.gtk.org/"},{default:r(()=>[...t[5]||(t[5]=[e("GTK",-1)])]),_:1}),t[8]||(t[8]=e(" 环境而设计的 autokey-gtk 和基于 ",-1)),n(a,{href:"https://www.qt.io/"},{default:r(()=>[...t[6]||(t[6]=[e("QT",-1)])]),_:1}),t[9]||(t[9]=e(" 的 autokey-qt。",-1))]),t[43]||(t[43]=o('<p>你可以从命令行安装任一变体：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install autokey-gtk</span></span></code></pre></div><p>安装完成后，使用 <code>autokey-gtk</code>（或 <code>autokey-qt</code>）运行它。</p><h3 id="探究界面" tabindex="-1">探究界面 <a class="header-anchor" href="#探究界面" aria-label="Permalink to “探究界面”">​</a></h3><p>在将 AutoKey 设置为在后台运行并自动执行操作之前，你首先需要对其进行配置。调出用户界面（UI）配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>autokey-gtk -c</span></span></code></pre></div><p>AutoKey 提供了一些预设配置的示例。你可能希望在熟悉 UI 时将他们留作备用，但是可以根据需要删除它们。</p><p><img src="https://opensource.com/sites/default/files/uploads/autokey-defaults.png" alt="AutoKey 用户界面" title="AutoKey UI"></p><p>左侧窗格包含一个文件夹式的短语和脚本的层次结构。“<ruby>短语<rt>Phrases</rt></ruby>” 代表要让 AutoKey 输入的文本。“<ruby>脚本<rt>Scripts</rt></ruby>” 是动态的、程序化的等效项，可以使用 Python 编写，并且获得与键盘击键发送到活动窗口基本相同的结果。</p><p>右侧窗格构建和配置短语和脚本。</p><p>对配置满意后，你可能希望在登录时自动运行 AutoKey，这样就不必每次都启动它。你可以通过在 “<ruby>首选项<rt>Preferences</rt></ruby>”菜单（“<ruby>编辑 -&gt; 首选项<rt>Edit -&gt; Preferences”</rt></ruby>”）中勾选 “<ruby>登录时自动启动 AutoKey<rt>Automatically start AutoKey at login</rt></ruby>”进行配置。</p><p><img src="https://opensource.com/sites/default/files/uploads/startautokey.png" alt="登录时自动启动 AutoKey" title="Automatically start AutoKey at login"></p><h3 id="使用-autokey-纠正常见的打字排版错误" tabindex="-1">使用 AutoKey 纠正常见的打字排版错误 <a class="header-anchor" href="#使用-autokey-纠正常见的打字排版错误" aria-label="Permalink to “使用 AutoKey 纠正常见的打字排版错误”">​</a></h3><p>修复常见的打字排版错误对于 AutoKey 来说是一个容易解决的问题。例如，我始终键入 “gerp” 来代替 “grep”。这里是如何配置 AutoKey 为你解决这些类型问题。</p><p>创建一个新的子文件夹，可以在其中将所有“打字排版错误校正”配置分组。在左侧窗格中选择 “My Phrases” ，然后选择 “<ruby>文件 -&gt; 新建 -&gt; 子文件夹<rt>File -&gt; New -&gt; Subfolder</rt></ruby>”。将子文件夹命名为 “Typos”。</p><p>在 “<ruby>文件 -&gt; 新建 -&gt; 短语<rt>File -&gt; New -&gt; Phrase</rt></ruby>” 中创建一个新短语。并将其称为 “grep”。</p><p>通过高亮选择短语 “grep”，然后在 <ruby>输入短语内容<rt>Enter phrase contents</rt></ruby>部分（替换默认的 “Enter phrase contents” 文本）中输入 “grep” ，配置 AutoKey 插入正确的关键词。</p><p>接下来，通过定义缩写来设置 AutoKey 如何触发此短语。点击用户界面底部紧邻 “<ruby>缩写<rt>Abbreviations</rt></ruby>” 的 “<ruby>设置<rt>Set</rt></ruby>”按钮。</p><p>在弹出的对话框中，单击 “<ruby>添加<rt>Add</rt></ruby>” 按钮，然后将 “gerp” 添加为新的缩写。勾选 “<ruby>删除键入的缩写<rt>Remove typed abbreviation</rt></ruby>”；此选项让 AutoKey 将任何键入 “gerp” 一词的替换为 “grep”。请不要勾选“<ruby>在键入单词的一部分时触发<rt>Trigger when typed as part of a word</rt></ruby>”，这样，如果你键入包含 “grep”的单词（例如 “fingerprint”），就不会尝试将其转换为 “fingreprint”。仅当将 “grep” 作为独立的单词键入时，此功能才有效。</p><p><img src="https://opensource.com/sites/default/files/uploads/autokey-set_abbreviation.png" alt="在 AutoKey 中设置缩写" title="Set abbreviation in AutoKey"></p><h3 id="限制对特定应用程序的更正" tabindex="-1">限制对特定应用程序的更正 <a class="header-anchor" href="#限制对特定应用程序的更正" aria-label="Permalink to “限制对特定应用程序的更正”">​</a></h3><p>你可能希望仅在某些应用程序（例如终端窗口）中打字排版错误时才应用校正。你可以通过设置 <ruby>窗口过滤器<rt>Window Filter</rt></ruby>进行配置。单击 “<ruby>设置<rt>Set</rt></ruby>” 按钮来定义。</p><p>设置<ruby>窗口过滤器<rt>Window Filter</rt></ruby>的最简单方法是让 AutoKey 为你检测窗口类型：</p><ol><li>启动一个新的终端窗口。</li><li>返回 AutoKey，单击 “<ruby>检测窗口属性<rt>Detect Window Properties</rt></ruby>”按钮。</li><li>单击终端窗口。</li></ol><p>这将自动填充窗口过滤器，可能的窗口类值为 <code>gnome-terminal-server.Gnome-terminal</code>。这足够了，因此单击 “OK”。</p><p><img src="https://opensource.com/sites/default/files/uploads/autokey-window_filter.png" alt="AutoKey 窗口过滤器" title="AutoKey Window Filter"></p><h3 id="保存并测试" tabindex="-1">保存并测试 <a class="header-anchor" href="#保存并测试" aria-label="Permalink to “保存并测试”">​</a></h3><p>对新配置满意后，请确保将其保存。 单击 “<ruby>文件<rt>File</rt></ruby>” ，然后选择 “<ruby>保存<rt>Save</rt></ruby>” 以使更改生效。</p><p>现在进行重要的测试！在你的终端窗口中，键入 “gerp” 紧跟一个空格，它将自动更正为 “grep”。要验证窗口过滤器是否正在运行，请尝试在浏览器 URL 栏或其他应用程序中键入单词 “gerp”。它并没有变化。</p>',29)),s("p",null,[t[11]||(t[11]=e("你可能会认为，使用 ",-1)),n(a,{href:"https://opensource.com/article/19/7/bash-aliases"},{default:r(()=>[...t[10]||(t[10]=[e("shell 别名",-1)])]),_:1}),t[12]||(t[12]=e(" 可以轻松解决此问题，我完全赞成！与别名不同，只要是面向命令行，无论你使用什么应用程序，AutoKey 都可以按规则纠正错误。",-1))]),t[44]||(t[44]=o('<p>例如，我在浏览器，集成开发环境和终端中输入的另一个常见打字错误 “openshfit” 替代为 “openshift”。别名不能完全解决此问题，而 AutoKey 可以在任何情况下纠正它。</p><h3 id="键入常用短语" tabindex="-1">键入常用短语 <a class="header-anchor" href="#键入常用短语" aria-label="Permalink to “键入常用短语”">​</a></h3><p>你可以通过许多其他方法来调用 AutoKey 的短语来帮助你。例如，作为从事 OpenShift 的站点可靠性工程师（SRE），我经常在命令行上输入 Kubernetes 命名空间名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>oc get pods -n openshift-managed-upgrade-operator</span></span></code></pre></div><p>这些名称空间是静态的，因此它们是键入特定命令时 AutoKey 可以为我插入的理想短语。</p><p>为此，我创建了一个名为 “Namespaces” 的短语子文件夹，并为我经常键入的每个命名空间添加了一个短语条目。</p><h3 id="分配热键" tabindex="-1">分配热键 <a class="header-anchor" href="#分配热键" aria-label="Permalink to “分配热键”">​</a></h3><p>接下来，也是最关键的一点，我为子文件夹分配了一个 “<ruby>热键<rt>hotkey</rt></ruby>”。每当我按下该热键时，它都会打开一个菜单，我可以在其中选择（要么使用 “方向键”+回车键要么使用数字）要插入的短语。这减少了我仅需几次击键就可以输入这些命令的击键次数。</p><p>“My Phrases” 文件夹中 AutoKey 的预配置示例使用 <code>Ctrl+F7</code> 热键进行配置。如果你将示例保留在 AutoKey 的默认配置中，请尝试一下。你应该在此处看到所有可用短语的菜单。使用数字或箭头键选择所需的项目。</p><h3 id="高级自动键入" tabindex="-1">高级自动键入 <a class="header-anchor" href="#高级自动键入" aria-label="Permalink to “高级自动键入”">​</a></h3>',10)),s("p",null,[t[14]||(t[14]=e("AutoKey 的 ",-1)),n(a,{href:"https://autokey.github.io/index.html"},{default:r(()=>[...t[13]||(t[13]=[e("脚本引擎",-1)])]),_:1}),t[15]||(t[15]=e(" 允许用户运行可以通过相同的缩写和热键系统调用的 Python 脚本。这些脚本可以通过支持的 API 的函数来完成诸如切换窗口、发送按键或执行鼠标单击之类的操作。",-1))]),s("p",null,[t[18]||(t[18]=e("AutoKey 用户非常欢迎这项功能，发布了自定义脚本供其他用户采用。例如，",-1)),n(a,{href:"https://github.com/luziferius/autokey_scripts"},{default:r(()=>[...t[16]||(t[16]=[e("NumpadIME 脚本",-1)])]),_:1}),t[19]||(t[19]=e(" 将数字键盘转换为旧的手机样式的文本输入方法，",-1)),n(a,{href:"https://github.com/AlienKevin/Emojis-AutoKey"},{default:r(()=>[...t[17]||(t[17]=[e("Emojis-AutoKey",-1)])]),_:1}),t[20]||(t[20]=e(" 可以通过将诸如: ",-1)),t[21]||(t[21]=s("code",null,":smile:",-1)),t[22]||(t[22]=e(" 之类的短语转换为它们等价的表情符号来轻松插入。",-1))]),t[45]||(t[45]=o(`<p>这是我设置的一个小脚本，该脚本进入 Tmux 的复制模式，以将前一行中的第一个单词复制到粘贴缓冲区中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from time import sleep</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 发送 Tmux 命令前缀（b 更改为 s）</span></span>
<span class="line"><span>keyboard.send_keys(&quot;&lt;ctr&gt;+s&quot;)</span></span>
<span class="line"><span># Enter copy mode</span></span>
<span class="line"><span>keyboard.send_key(&quot;[&quot;)</span></span>
<span class="line"><span>sleep(0.01)</span></span>
<span class="line"><span># Move cursor up one line</span></span>
<span class="line"><span>keyboard.send_keys(&quot;k&quot;)</span></span>
<span class="line"><span>sleep(0.01)</span></span>
<span class="line"><span># Move cursor to start of line</span></span>
<span class="line"><span>keyboard.send_keys(&quot;0&quot;)</span></span>
<span class="line"><span>sleep(0.01)</span></span>
<span class="line"><span># Start mark</span></span>
<span class="line"><span>keyboard.send_keys(&quot; &quot;)</span></span>
<span class="line"><span>sleep(0.01)</span></span>
<span class="line"><span># Move cursor to end of word</span></span>
<span class="line"><span>keyboard.send_keys(&quot;e&quot;)</span></span>
<span class="line"><span>sleep(0.01)</span></span>
<span class="line"><span># Add to copy buffer</span></span>
<span class="line"><span>keyboard.send_keys(&quot;\`&lt;Ctrl&gt;\`+m&quot;)</span></span></code></pre></div><p>之所以有 <code>sleep</code> 函数，是因为 Tmux 有时无法跟上 AutoKey 发送击键的速度，并且它们对整体执行时间的影响可忽略不计。</p><h3 id="使用-autokey-自动化" tabindex="-1">使用 AutoKey 自动化 <a class="header-anchor" href="#使用-autokey-自动化" aria-label="Permalink to “使用 AutoKey 自动化”">​</a></h3><p>我希望你喜欢这篇使用 AutoKey 进行键盘自动化的探索，它为你提供了有关如何改善工作流程的一些好主意。如果你在使用 AutoKey 时有什么有用的或新颖的方法，一定要在下面的评论中分享。</p><hr>`,6)),s("p",null,[t[24]||(t[24]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/21/2/linux-autokey"},{default:r(()=>[...t[23]||(t[23]=[e("https://opensource.com/article/21/2/linux-autokey",-1)])]),_:1})]),s("p",null,[t[29]||(t[29]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/mbargenquast"},{default:r(()=>[...t[25]||(t[25]=[e("Matt Bargenquast",-1)])]),_:1}),t[30]||(t[30]=e(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[26]||(t[26]=[e("lujun9972",-1)])]),_:1}),t[31]||(t[31]=e(" 译者：",-1)),n(a,{href:"https://github.com/stevenzdg988"},{default:r(()=>[...t[27]||(t[27]=[e("stevenzdg988",-1)])]),_:1}),t[32]||(t[32]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...t[28]||(t[28]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[35]||(t[35]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[33]||(t[33]=[e("LCTT",-1)])]),_:1}),t[36]||(t[36]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:r(()=>[...t[34]||(t[34]=[e("Linux中国",-1)])]),_:1}),t[37]||(t[37]=e(" 荣誉推出",-1))])])}const K=i(d,[["render",y]]);export{x as __pageData,K as default};
